const { useState } = React;

function App() {
  const [page, setPage] = useState("landing");

  // Navigation handlers
  const goToSignUp = () => setPage("signup");
  const goToPricing = () => setPage("pricing");
  const goToLanding = () => setPage("landing");

  // Components for pages
  const Navbar = () => (
    <nav style={styles.navbar} aria-label="Primary navigation">
      <div style={styles.logo} tabIndex={0} onClick={goToLanding} role="link" aria-label="Nimbus home">
        Nimbus
      </div>
      <ul style={styles.navLinks}>
        <li>
          <button
            style={{ ...styles.navButton, ...styles.navButtonActive }}
            aria-current={page === "landing" ? "page" : undefined}
            onClick={goToLanding}
          >
            Features
          </button>
        </li>
        <li>
          <button
            style={styles.navButton}
            onClick={goToPricing}
            aria-current={page === "pricing" ? "page" : undefined}
          >
            Pricing
          </button>
        </li>
        <li>
          <button style={styles.navButton} onClick={() => alert("About Nimbus: Nimbus is a cloud storage platform.") }>
            About
          </button>
        </li>
      </ul>
      <button style={styles.getStartedButton} onClick={goToSignUp} aria-label="Get started with Nimbus">
        Get started
      </button>
    </nav>
  );

  const LandingPage = () => (
    <main style={styles.main}>
      <section style={styles.heroSection} aria-label="Hero">
        <div style={styles.heroText}>
          <h1 style={styles.heroHeadline}>Cloud storage made simple</h1>
          <p style={styles.heroParagraph}>
            Nimbus offers fast, secure, and synced cloud storage solutions for all your needs.
          </p>
          <div style={styles.heroButtons}>
            <button style={styles.tryFreeButton} onClick={goToSignUp} aria-label="Try Nimbus free">
              Try free
            </button>
            <button
              style={styles.learnMoreButton}
              onClick={() => alert("Learn more about Nimbus cloud storage.")}
              aria-label="Learn more about Nimbus"
            >
              Learn more
            </button>
          </div>
        </div>
        <div style={styles.heroImageWrapper}>
          <img
            src="/runtime/photos/cloud_storage.jpg"
            alt="Cloud storage illustration"
            style={styles.heroImage}
            loading="lazy"
          />
        </div>
      </section>

      <section style={styles.featuresSection} aria-label="Features">
        <FeatureCard
          icon="⚡"
          title="Fast"
          description="Experience lightning-fast upload and download speeds to keep your files accessible instantly."
        />
        <FeatureCard
          icon="🔒"
          title="Secure"
          description="Your data is protected with top-tier encryption and security protocols."
        />
        <FeatureCard
          icon="🔄"
          title="Synced"
          description="Keep your files synchronized across all your devices seamlessly."
        />
      </section>
    </main>
  );

  const FeatureCard = ({ icon, title, description }) => (
    <article style={styles.featureCard} tabIndex={0} aria-label={`${title} feature`}> 
      <div style={styles.featureIcon} aria-hidden="true">
        {icon}
      </div>
      <h3 style={styles.featureTitle}>{title}</h3>
      <p style={styles.featureDescription}>{description}</p>
    </article>
  );

  const SignUpPage = () => {
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [errors, setErrors] = useState({});

    const validate = () => {
      const newErrors = {};
      if (!email) newErrors.email = "Email is required.";
      else if (!/^\S+@\S+\.\S+$/.test(email)) newErrors.email = "Email is invalid.";
      if (!password) newErrors.password = "Password is required.";
      else if (password.length < 6) newErrors.password = "Password must be at least 6 characters.";
      setErrors(newErrors);
      return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = (e) => {
      e.preventDefault();
      if (validate()) {
        alert(`Signed up with email: ${email}`);
        setEmail("");
        setPassword("");
        setErrors({});
        setPage("landing");
      }
    };

    return (
      <main style={styles.formMain}>
        <h2 style={styles.formTitle}>Sign Up</h2>
        <form onSubmit={handleSubmit} noValidate aria-label="Sign up form">
          <label htmlFor="email" style={styles.formLabel}>
            Email
          </label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={styles.formInput}
            aria-describedby={errors.email ? "email-error" : undefined}
            aria-invalid={errors.email ? "true" : "false"}
            required
          />
          {errors.email && (
            <p id="email-error" role="alert" style={styles.errorMessage}>
              {errors.email}
            </p>
          )}

          <label htmlFor="password" style={styles.formLabel}>
            Password
          </label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={styles.formInput}
            aria-describedby={errors.password ? "password-error" : undefined}
            aria-invalid={errors.password ? "true" : "false"}
            required
          />
          {errors.password && (
            <p id="password-error" role="alert" style={styles.errorMessage}>
              {errors.password}
            </p>
          )}

          <div style={styles.formButtons}>
            <button type="submit" style={styles.tryFreeButton} aria-label="Submit sign up form">
              Sign Up
            </button>
            <button type="button" style={styles.learnMoreButton} onClick={goToLanding} aria-label="Back to landing page">
              Cancel
            </button>
          </div>
        </form>
      </main>
    );
  };

  const PricingPage = () => {
    return (
      <main style={styles.pricingMain}>
        <h2 style={styles.formTitle}>Pricing</h2>
        <p style={{ marginBottom: 20 }}>
          Choose the plan that fits your needs.
        </p>
        <ul style={styles.pricingList}>
          <li style={styles.pricingItem} tabIndex={0} aria-label="Free plan">
            <h3>Free</h3>
            <p>5 GB storage</p>
            <p>Basic support</p>
            <p>Try free now!</p>
          </li>
          <li style={styles.pricingItem} tabIndex={0} aria-label="Pro plan">
            <h3>Pro</h3>
            <p>1 TB storage</p>
            <p>Priority support</p>
            <p>$9.99/month</p>
          </li>
          <li style={styles.pricingItem} tabIndex={0} aria-label="Enterprise plan">
            <h3>Enterprise</h3>
            <p>Unlimited storage</p>
            <p>Dedicated support</p>
            <p>Contact us</p>
          </li>
        </ul>
        <button style={styles.learnMoreButton} onClick={goToLanding} aria-label="Back to landing page">
          Back
        </button>
      </main>
    );
  };

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background-color: #faf7f3;
          color: #333;
        }
        button {
          cursor: pointer;
          font-family: inherit;
        }
        button:focus, input:focus {
          outline: 3px solid #4a90e2;
          outline-offset: 2px;
        }
      `}</style>
